type UserPreferences = Record<string, unknown>

async function getUserPreferences(): Promise<UserPreferences> {
  try {
    const res = await fetch('https://api.example.com/user/preferences', {
      cache: 'no-store',
    })
    if (!res.ok) {
      throw new Error(`HTTP ${res.status}`)
    }
    return res.json()
  } catch {
    return {
      theme: 'system',
      emailNotifications: true,
    }
  }
}

function formatPreferenceValue(value: unknown): string {
  if (value === null || value === undefined) {
    return String(value)
  }
  if (typeof value === 'object') {
    return JSON.stringify(value, null, 2)
  }
  return String(value)
}

export default async function UserDashboard() {
  const preferences = await getUserPreferences()

  return (
    <div>
      <h2>User Dashboard</h2>
      <dl>
        {Object.entries(preferences).map(([key, value]) => (
          <div key={key}>
            <dt>{key}</dt>
            <dd>
              {typeof value === 'object' && value !== null ? (
                <pre>{formatPreferenceValue(value)}</pre>
              ) : (
                formatPreferenceValue(value)
              )}
            </dd>
          </div>
        ))}
      </dl>
    </div>
  )
}

